package local.tvmorph.tv;
import android.content.Context;import java.io.*;import java.security.*;import java.util.*;import java.util.concurrent.*;import java.util.zip.*;import javax.crypto.*;import javax.crypto.spec.*;import org.json.*;
/** Short-lived, encrypted catalog cache. Catalog metadata is encrypted, including any provider image URLs. */
final class CatalogDisk {
 interface Keys{javax.crypto.SecretKey get()throws Exception;}
 static final long TTL=7*24*60*60*1000L;static final long FRESH=6*60*60*1000L;private static final ExecutorService writer=CatalogWriteQueue.create();
 final Context context;final Keys keys;CatalogDisk(Context c,Keys k){context=c;keys=k;}
 String epoch(){return context==null?"test":context.getSharedPreferences("iptv-metadata",0).getString("epoch","first");}
 void reset(){if(context!=null)context.getSharedPreferences("iptv-metadata",0).edit().putString("epoch",UUID.randomUUID().toString()).apply();}
 File file(String profile,String epoch,String key)throws Exception{File dir=new File(context.getCacheDir(),"tvmorph-catalog");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("Cache directory unavailable");byte[] hash=MessageDigest.getInstance("SHA-256").digest(("schema3-release-year:"+profile+":"+epoch+":"+key).getBytes("UTF-8"));StringBuilder name=new StringBuilder("catalog-");for(byte b:hash)name.append(String.format(Locale.US,"%02x",b&255));return new File(dir,name+".bin");}
 long savedAt(String profile,String epoch,String key){try{return file(profile,epoch,key).lastModified();}catch(Exception e){return 0;}}
 JSONArray read(String profile,String epoch,String key){if(context==null)return null;File f=null;try{f=file(profile,epoch,key);if(!f.isFile()||System.currentTimeMillis()-f.lastModified()>TTL||f.length()>8*1024*1024)return null;try(InputStream source=new FileInputStream(f)){byte[] iv=new byte[12];new DataInputStream(source).readFully(iv);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,keys.get(),new GCMParameterSpec(128,iv));try(InputStream gzip=new GZIPInputStream(new CipherInputStream(source,cipher));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=gzip.read(bytes))!=-1){if(out.size()+n>24*1024*1024)throw new IOException("Catalog too large");out.write(bytes,0,n);}return new JSONArray(out.toString("UTF-8"));}}}catch(Exception ignored){if(f!=null)f.delete();return null;}}
 void save(String profile,String epoch,String key,JSONArray rows){if(context==null)return;writer.execute(()->{File tmp=null;try{File target=file(profile,epoch,key);tmp=new File(target.getParentFile(),target.getName()+"."+UUID.randomUUID()+".tmp");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,keys.get());try(OutputStream file=new FileOutputStream(tmp)){file.write(cipher.getIV());try(Writer json=new OutputStreamWriter(new GZIPOutputStream(new CipherOutputStream(file,cipher)),"UTF-8")){json.write('[');for(int i=0;i<rows.length();i++){if(i>0)json.write(',');json.write(rows.getJSONObject(i).toString());}json.write(']');}}if(!tmp.renameTo(target))tmp.delete();File[] files=target.getParentFile().listFiles((dir,name)->name.startsWith("catalog-")&&name.endsWith(".bin"));if(files!=null){Arrays.sort(files,(a,b)->Long.compare(b.lastModified(),a.lastModified()));long bytes=0;for(int i=0;i<files.length;i++){bytes+=files[i].length();if(i>=24||bytes>48*1024*1024L||System.currentTimeMillis()-files[i].lastModified()>TTL)files[i].delete();}}}catch(Exception ignored){if(tmp!=null)tmp.delete();}});}
}
